      "zhDeck": "为什么说 AI 行业在“造模型”上投入过多，而在“工作流扩散”上投入不足？为什么靠 AI 裁员省钱的公司几乎全败，做大营收的客户却能跑通？Shyam Sankar 详解企业状态机与运营数据主权、前线部署工程的产品战略，并复盘 Anthropic 与五角大楼冲突。",
