            "根源在于加速器的工作原理：它靠电磁场加速，因此只能加速带电粒子（电子、质子或带正电的原子核）。电子不参与强核力，很难触发核反应，打在靶上大半变成废热；质子或 α 粒子虽然能触发核反应，但它们带正电，会受到同样带正电的靶原子核排斥，绝大部分能量同样化作废热，转化效率极低。当 PETtrace 800 用质子轰击氧-18 制造氟-18 时，每 800 个质子里平均只有 1 个能进入氧原子核。"
