            "第二种制造粒子碰撞的办法是利用核裂变：不稳定的原子核被中子击中后分裂。一条路是直接提取核裂变自然生成的产物，比如钼-99 就是铀-235 和钚-239 裂变的天然产物，锶-90 也常从乏燃料中提取。",
